INSERT OR REPLACE INTO content (slug, title, body, meta) VALUES ('announcement', 'Site announcement', '{"text": "New clients welcome — virtual across South Carolina, in person in Mount Pleasant. Free 15-minute consultations available."}', '{}');
INSERT OR REPLACE INTO content (slug, title, body, meta) VALUES ('faq', 'Frequently asked questions', '{"items": [{"q": "Where can you see clients?", "a": "I am available virtually throughout the state of South Carolina. Unfortunately, if you are out of state I cannot provide services. In-person sessions are available at my office in Mount Pleasant."}, {"q": "What is Trauma-Informed Yoga?", "a": "Trauma-Informed Yoga is an approach to teaching and practicing yoga that makes it suitable for everybody and every body. I practice mostly Yin Yoga, which focuses on long, gentle stretches rather than balance or strength. Trauma-Informed yoga can be used as an adjunct to treatment, or as a stand-alone service. It can be done in-person or virtually."}, {"q": "What is EMDR?", "a": "Eye Movement Desensitization and Reprocessing Therapy is an evidence-based treatment for trauma and post-traumatic stress disorder. It is a way of gently re-engaging with traumatic memories or experiences to make them less triggering."}, {"q": "What is Prolonged Exposure Therapy?", "a": "Prolonged Exposure Therapy is an evidence-based treatment for post-traumatic stress disorder based in a Cognitive top-down approach. It combines two types of exposure therapies (imaginary and in-vivo) to reduce trauma symptoms."}, {"q": "How long is treatment?", "a": "Most people see symptom relief in 8–10 sessions, but many people stay in therapy longer for ongoing, regular support. Length of treatment is a collaborative discussion."}, {"q": "Do you accept insurance?", "a": "Yes. I am in network with Cigna and Aetna. I can provide you with a superbill to submit to your insurance company for possible reimbursement."}, {"q": "Where is the office?", "a": "1007 Johnnie Dodds Blvd. Suite #129, Mount Pleasant, SC 29464."}]}', '{}');
INSERT OR REPLACE INTO content (slug, title, body, meta) VALUES ('contact', 'Contact & availability', '{"email": "rebekah@papercranewellness.com", "phone": "(843) 555-0148", "phoneHref": "tel:+18435550148", "address": "1007 Johnnie Dodds Blvd, Suite #129, Mount Pleasant, SC 29464", "location": "Mount Pleasant, SC (in-person) · Virtual across South Carolina", "hours": "Mon–Fri by appointment", "insurance": "In-network with Cigna and Aetna. Superbills available for out-of-network reimbursement."}', '{}');
